package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="transferencia_financeira",schema="adm_eclesial") public class TransferenciaFinanceira { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="conta_origem_id",nullable=false) Long contaOrigemId; @Column(name="conta_destino_id",nullable=false) Long contaDestinoId; @Column(name="movimentacao_origem_id",nullable=false) Long movimentacaoOrigemId; @Column(name="movimentacao_destino_id",nullable=false) Long movimentacaoDestinoId; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @Column(name="data_transferencia",nullable=false) LocalDate dataTransferencia; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getContaOrigemId(){return contaOrigemId;} public Long getContaDestinoId(){return contaDestinoId;} public Long getMovimentacaoOrigemId(){return movimentacaoOrigemId;} public Long getMovimentacaoDestinoId(){return movimentacaoDestinoId;} public BigDecimal getValor(){return valor;} public LocalDate getDataTransferencia(){return dataTransferencia;} public String getObservacao(){return observacao;} public void setContaOrigemId(Long v){contaOrigemId=v;} public void setContaDestinoId(Long v){contaDestinoId=v;} public void setMovimentacaoOrigemId(Long v){movimentacaoOrigemId=v;} public void setMovimentacaoDestinoId(Long v){movimentacaoDestinoId=v;} public void setValor(BigDecimal v){valor=v;} public void setDataTransferencia(LocalDate v){dataTransferencia=v;} public void setObservacao(String v){observacao=v;} }